window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==parent||event.data?.type!=='motion-settings')return;const nav=document.querySelector('.mobile-nav');if(!nav)return;const rules={'duration':[120,800,'ms','--motion-duration'],'bounce':[1,1.7,'','--motion-bounce'],'stretch':[0,.1,'','--stretch-amount'],'resistance':[0,.5,'','--edge-resistance'],'glass':[.35,.95,'','--glass-opacity']};for(const [key,[min,max,unit,property]] of Object.entries(rules)){const n=Number(event.data[key]);if(Number.isFinite(n))nav.style.setProperty(property,Math.max(min,Math.min(max,n))+unit);}});parent.postMessage({type:'motion-ready'},location.origin);